    Ik = (e) => {
        const t = e.toLowerCase();
        return t.includes("تحميل") || t.includes("download")
            ? en
            : t.includes("usb") || t.includes("فلاشة") || t.includes("bootable")
              ? cu
              : t.includes("bios") || t.includes("uefi")
                ? zo
                : t.includes("تثبيت") || t.includes("install")
                  ? St
                  : t.includes("شبكة") || t.includes("network")
                    ? Gi
                    : t.includes("مستخدم") || t.includes("user")
                      ? du
                      : t.includes("قرص") || t.includes("partition") || t.includes("disk")
                        ? St
                        : t.includes("grub") || t.includes("boot")
                          ? Qc
                          : t.includes("تحديث") || t.includes("update") || t.includes("reboot")
                            ? zv
                            : t.includes("virtualization") || t.includes("افتراضية")
                              ? kn
                              : t.includes("virtualbox") || t.includes("vmware")
                                ? au
                                : t.includes("import") || t.includes("استيراد")
                                  ? xn
                                  : t.includes("إعداد") ||
                                      t.includes("ضبط") ||
                                      t.includes("configure") ||
                                      t.includes("setting")
                                    ? zo
                                    : t.includes("تشغيل") || t.includes("start") || t.includes("run")
                                      ? Qc
                                      : t.includes("guest") || t.includes("additions")
                                        ? Rg
                                        : t.includes("فتح") || t.includes("open")
                                          ? xn
                                          : t.includes("أدوات") || t.includes("tools")
                                            ? Ur
                                            : t.includes("استنساخ") ||
                                                t.includes("clone") ||
                                                t.includes("github") ||
                                                t.includes("python") ||
                                                t.includes("مكتبات")
                                              ? $i
                                              : ot;
    },
